121	    expect(observations.length).toBeLessThan(16);
122	    const url = `${scope}${relative}`,
123	      address = new URL(child.ready.listenUrl as string);
124	    const execute = createRawHttpExchangeExecutor(
125	      { transport: "plain", host: address.hostname, port: Number(address.port) },
126	      {
127	        requestTimeoutMs: 5000,
128	        maximumBodyBytes: 131072,
129	        maximumHeaderBytes: 16384,
130	        exactMode: {
131	          scope,
132	          profile: "transactional",
133	          routes: [{ method, url }],
134	          maximumRequestHeaderBytes: 16384,
135	          maximumRequestBodyBytes: 65536,
136	          defaultCredentialRef: authenticated ? "writer" : "anonymous",
137	          credentialHandles: [
138	            { id: "writer", headerNames: ["authorization"] },
139	            { id: "anonymous", headerNames: [] },
140	          ],
141	          resolveCredentials: ({ credentialRef }) =>
142	            credentialRef === "writer" ? { authorization: `Bearer ${token}` } : {},
143	        },
144	      },
145	    );
146	    const response = await execute({
147	      method,
148	      url,
149	      signal: controller.signal,
150	      ...(authenticated ? { credentialRef: "writer" } : {}),
151	      raw: {
152	        headerLines:
153	          input === undefined
154	            ? []
155	            : [
156	                { name: "content-type", value: "application/json" },
157	                { name: "idempotency-key", value: "discovery-create" },
158	              ],
159	        ...(input === undefined ? {} : { bodyBytes: Buffer.from(JSON.stringify(input)) }),
160	      },
161	    });
162	    expect(response.exactRequest?.writeState).toBe("complete");
163	    expect(
164	      response.exactRequest?.headerLines.find((h) => h.name.toLowerCase() === "host")?.value,
165	    ).toBe("reference.invalid");
166	    if (!response.wireResponseBytes?.length) throw new Error("missing actual wire response");
167	    expect(response.bodyOctets).toBe(Buffer.byteLength(response.bodyText));
168	    observations.push({
169	      method,
170	      url,
171	      status: response.status,
172	      bodyOctets: response.bodyOctets,
173	      bodySha256: hash(response.bodyText),
174	      wireSha256: hash(response.wireResponseBytes),
175	    });
176	    expect(response.status).toBe(expectedStatus);
177	    expect(response.headers["x-bdp-development"]).toBe("non-attesting");
178	    return response;
179	  }
