193	    binding = installedTransactionBinding(child.ready, source, fixture);
194	    expect(child.ready).toMatchObject({
195	      profile: "transactional",
196	      history: false,
197	      claimEligible: false,
198	    });
199	    for (const method of ["GET", "HEAD"] as const)
200	      for (const route of ["", "bdp.json", "operations/"]) {
201	        const response = await exchange(route, method, true, route === "" ? 204 : 200);
202	        expect(response.headers["x-bdp-development-limit"]).toBeUndefined();
203	        if (route === "") {
204	          expect(response.headers.link).toBe(
205	            `<${new URL("bdp.json", scope).href}>; rel="service-desc"; type="application/json"`,
206	          );
207	          expect(response.bodyText).toBe("");
208	        } else if (method === "HEAD") expect(response.bodyText).toBe("");
209	        else if (route === "bdp.json") parseTransactionalDiscovery(JSON.parse(response.bodyText));
210	        else
211	          expect(
212	            Object.keys(parseTransactionalOperationDirectory(JSON.parse(response.bodyText))),
213	          ).toHaveLength(12);
214	      }
215	    for (const route of ["", "bdp.json", "operations/"]) {
216	      const response = await exchange(route, "GET", false, 401);
217	      expect(response.headers.link).toBeUndefined();
218	      for (const name of ["bdp-scope-epoch", "bdp-authorization-view", "bdp-scope-position"])
219	        expect(response.headers[name]).toBeUndefined();
220	      expect(response.bodyText).not.toContain(`${scope}operations/`);
221	    }
