249	      expect(response.headers["bdp-scope-epoch"]).toMatch(/\S+/);
250	      expect(response.headers["bdp-authorization-view"]).toMatch(/\S+/);
251	      expect(response.headers["bdp-scope-position"]).toBe("pos-1");
252	    }
253	    expect(new Set(observations.map((o) => o.url))).toEqual(
254	      new Set([...targets].map((target) => `${scope}${target}`)),
