        f.expectedAbort();
        await closing;
        await f.events.closed;
        expect(f.events.state).toMatchObject({
          exitSeen: true,
          closeSeen: true,
          code: 0,
          signal: null,
        });
        d3PidAbsent(f.child.child.pid);
      },
    );
  }, 60000);
}

